#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int odwroc(int n) {
    int wynik = 0;
    while (n > 0) {
        wynik = wynik * 10 + n % 10;
        n /= 10;
    }
    return wynik;
}

bool czyPierwsza(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2)
        if (n % i == 0) return false;
    return true;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    vector<int> tab;
    while (plik >> n) tab.push_back(n);

    cout << "a) Palindromy liczbowe:" << endl;
    vector<int> palindromy;
    for (int x : tab) {
        int odwr = odwroc(x);
        if (odwr == x) {
            cout << "   " << x << " (odwrocone: " << odwr << ") - palindrom" << endl;
            palindromy.push_back(x);
        }
    }
    cout << "   Ilosc palindromow: " << palindromy.size() << endl;

    cout << endl << "b) Palindromy pierwsze:" << endl;
    int ile = 0;
    for (int x : palindromy) {
        if (czyPierwsza(x)) {
            cout << "   " << x << " - palindrom i pierwsza" << endl;
            ile++;
        }
    }
    cout << "   Ilosc: " << ile << endl;
    return 0;
}
```

